INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(31311, 'Matthew 26:3', 'Matthew', 26, 3, 'په همدې وخت کې مشران کاهنان او د قوم مشران د لوی کاهن قیافا په کور کې سره راټول شول', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_3.mp3', '', 1761754199, 1761754199),
(31312, 'Matthew 26:4', 'Matthew', 26, 4, 'او هغوی یوه دسیسه جوړه کړه چې عیسی په یو چل راونیسي او ویې وژني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_4.mp3', '', 1761754199, 1761754199),
(31313, 'Matthew 26:5', 'Matthew', 26, 5, 'خو هغوی وویل: «دا کار باید د اختر په ورځو کې ونه شي، هسې نه چې د خلکو په منځ کې شور او غوغا جوړه شي.» د عیسی په سر باندې عطر اچول (مرقوس ۱۴‏:‌۳‌‏-‌۹ او یوحنا ۱۲‏:‌۱‌‏-‌۸)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_5.mp3', '', 1761754199, 1761754199),
(31314, 'Matthew 26:6', 'Matthew', 26, 6, 'کله چې عیسی په بیت‌عنیا کې د شمعون کور ته لاړ چې مخکې د جذام په ناروغۍ اخته ؤ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_6.mp3', '', 1761754199, 1761754199),
(31315, 'Matthew 26:7', 'Matthew', 26, 7, 'یوه ښځه چې د قیمتي عطرو ‎څخه ډک د مرمرو بوتل ورسره ؤ راغله او په داسې حال کې چې عیسی ډوډۍ ته ناست ؤ هغه عطر یې د هغه په سر باندې واچول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_7.mp3', '', 1761754199, 1761754199),
(31316, 'Matthew 26:8', 'Matthew', 26, 8, 'کله چې شاګردانو دا ولیدل، نو خفه شول او ویې ویل: «دا عطر ولې بېځایه مصرف شول؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_8.mp3', '', 1761754199, 1761754199),
(31317, 'Matthew 26:9', 'Matthew', 26, 9, 'کېدای شول چې هغه په لوړه بیه خرڅ شوي وای او پیسې یې غریبانو ته ورکړل شوې وای.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_9.mp3', '', 1761754199, 1761754199),
(31318, 'Matthew 26:10', 'Matthew', 26, 10, 'عیسی پوه شو چې هغوی څه وویل او هغوی ته یې وویل: «تاسو ولې هغه ښځه تنګوئ؟ هغې زما سره ښه کار کړی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_10.mp3', '', 1761754199, 1761754199),
(31319, 'Matthew 26:11', 'Matthew', 26, 11, 'غریبان به تل ستاسو سره وي، خو زه به تل تاسو سره نه یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_11.mp3', '', 1761754199, 1761754199),
(31320, 'Matthew 26:12', 'Matthew', 26, 12, 'هغې چې دا عطر زما په بدن باندې واچول، نو زه یې ښخولو ته تیار کړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_12.mp3', '', 1761754199, 1761754199),
(31321, 'Matthew 26:13', 'Matthew', 26, 13, 'په یقین سره زه تاسو ته دا وایم چې د نړۍ په هرځای کې چې دا زېری ورکول کیږي، نو دې ښځې چې څه کړي دي خلک به هغه یادوي.» یهودا اسخریوتي د عیسی سره خیانت کوي (مرقوس ۱۴‏:‌۱۰‌‏-‌۱۱ او لوقا ۲۲‏:‌۳‌‏-‌۶)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_13.mp3', '', 1761754199, 1761754199),
(31322, 'Matthew 26:14', 'Matthew', 26, 14, 'بیا یهودا اسخریوتي چې د هغو دولسو شاګردانو څخه ؤ مشرانو کاهنانو ته ورغی', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_14.mp3', '', 1761754199, 1761754199),
(31323, 'Matthew 26:15', 'Matthew', 26, 15, 'او پوښتنه یې وکړه: «که زه عیسی تاسو ته دروسپارم نو ماته به څه راکړئ؟» نو هغوی ورته د سپینو زرو دېرش سکې ورکړې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_15.mp3', '', 1761754199, 1761754199),
(31324, 'Matthew 26:16', 'Matthew', 26, 16, 'د هماغه وخت نه هغه په دې لټه کې ؤ چې یوه موقعه پیدا کړي او عیسی هغوی ته په لاس ورکړي. عیسی د خپلو شاګردانو سره د فسحې د اختر ډوډۍ خوري (مرقوس ۱۴‏:‌۱۲‌‏-‌۲۱ او لوقا ۲۲‏:‌۷‌‏-‌۱۳، ۲۲‏:‌۲۱‌‏-‌۲۳ او یوحنا ۱۳‏:‌۲۱‌‏-‌۳۰)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_16.mp3', '', 1761754199, 1761754199),
(31325, 'Matthew 26:17', 'Matthew', 26, 17, 'د فطیرې ډوډۍ د اختر په لومړۍ ورځ شاګردان عیسی ته راغلل او پوښتنه یې ترې وکړه: «په کوم ځای کې غواړې چې د فسحې ډوډۍ درته تیاره کړو؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_17.mp3', '', 1761754199, 1761754199),
(31326, 'Matthew 26:18', 'Matthew', 26, 18, 'هغه وویل: «په ښار کې فلاني سړي ته ورشئ او ورته ووایئ: استاذ وایي چې زما ټاکل شوی وخت رانژدې شوی دی، زه به د فسحې اختر د خپلو شاګردانو سره ستا په کور کې ولمانځم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_18.mp3', '', 1761754199, 1761754199),
(31327, 'Matthew 26:19', 'Matthew', 26, 19, 'نو څنګه چې عیسی ورته ویلي وو شاګردانو هماغسې وکړل او د فسحې ډوډۍ یې تیاره کړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_19.mp3', '', 1761754199, 1761754199),
(31328, 'Matthew 26:20', 'Matthew', 26, 20, 'کله چې ماښام شو، نو عیسی د خپلو دولسو شاګردانو سره دسترخوان ته کښېناست.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_20.mp3', '', 1761754199, 1761754199),
(31329, 'Matthew 26:21', 'Matthew', 26, 21, 'د ډوډۍ په وخت کې عیسی وویل: «په یقین سره زه تاسو ته دا وایم چې په تاسو کې به یو کس زما سره خیانت وکړي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_21.mp3', '', 1761754199, 1761754199),
(31330, 'Matthew 26:22', 'Matthew', 26, 22, 'شاګردان ډېر غمجن شول او هر یو د عیسی نه پوښتنه کوله: «استاذه! ایا هغه زه یم؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_22.mp3', '', 1761754199, 1761754199),
(31331, 'Matthew 26:23', 'Matthew', 26, 23, 'عیسی ځواب ورکړ: «چا چې زما سره په دې کاسه کې لاس ښکته کړ هغه به زما سره خیانت کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_23.mp3', '', 1761754199, 1761754199),
(31332, 'Matthew 26:24', 'Matthew', 26, 24, 'لکه څنګه چې د هغه په هکله د خدای په کلام کې لیکل شوي دي، د انسان زوی باید مړ شي خو افسوس د هغه چا په حال چې د انسان د زوی سره خیانت کوي. د هغه سړي دپاره به دا ښه وای چې هېڅ پیدا شوی نه وای.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_24.mp3', '', 1761754199, 1761754199),
(31333, 'Matthew 26:25', 'Matthew', 26, 25, 'بیا یهودا خاین وویل: «استاذه! ایا هغه زه یم؟» عیسی په ځواب کې وویل: «تا په خپله وویل.» د څښتن غوره ماښامی (مرقوس ۱۴‏:‌۲۲‌‏-‌۲۶ او لوقا ۲۲‏:‌۱۴‌‏-‌۲۰ او لومړی قرنتیان ۱۱‏:‌۲۳‌‏-‌۲۵)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_25.mp3', '', 1761754199, 1761754199),
(31334, 'Matthew 26:26', 'Matthew', 26, 26, 'د ډوډۍ خوړلو په وخت کې عیسی یوه ډوډۍ راواخیستله، شکر یې پرې وویست او هغه یې ماته کړه او شاګردانو ته یې ورکړه او ویې ویل: «دا واخلئ او ویې خورئ، دا زما بدن دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_26.mp3', '', 1761754199, 1761754199),
(31335, 'Matthew 26:27', 'Matthew', 26, 27, 'بیا هغه پیاله راواخیستله، د خدای شکر یې وویست او شاګردانو ته یې ورکړه او ویې ویل: «تاسو ټول دا وڅښئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_27.mp3', '', 1761754199, 1761754199),
(31336, 'Matthew 26:28', 'Matthew', 26, 28, 'دا زما وینه ده چې د ډېرو خلکو د ګناهونو د بخښنې دپاره توییږي. دا د انسان سره د خدای د لوظ نښه ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_28.mp3', '', 1761754199, 1761754199),
(31337, 'Matthew 26:29', 'Matthew', 26, 29, 'زه تاسو ته وایم چې زه به بیا تر هغې ورځې پورې دا د انګورو شربت ونه څښم ترڅو د خپل پلار په پاچاهۍ کې یې ستاسو سره بیا ونه څښم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_29.mp3', '', 1761754199, 1761754199),
(31338, 'Matthew 26:30', 'Matthew', 26, 30, 'بیا د یوې روحاني سندرې د ویلو څخه وروسته د زیتون غره ته لاړل. د پطروس د انکار په هکله د عیسی پېشګويي (مرقوس ۱۴‏:‌۲۷‌‏-‌۳۱ او لوقا ۲۲‏:‌۳۱‌‏-‌۳۴ او یوحنا ۱۳‏:‌۳۶‌‏-‌۳۸)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_30.mp3', '', 1761754199, 1761754199),
(31339, 'Matthew 26:31', 'Matthew', 26, 31, 'بیا عیسی خپلو شاګردانو ته وویل: «همدا نن شپه به تاسو ټول ما پرېږدئ، ځکه چې د خدای په کلام کې لیکل شوي دي: زه به شپون ووهم او د رمې پسونه به خواره واره شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_31.mp3', '', 1761754199, 1761754199),
(31340, 'Matthew 26:32', 'Matthew', 26, 32, 'خو کله چې بیا راژوندی شم، نو ستاسو نه مخکې به جلیل ته لاړ شم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_32.mp3', '', 1761754199, 1761754199),
(31341, 'Matthew 26:33', 'Matthew', 26, 33, 'پطروس په ځواب کې وویل: «که ټول تا پرېږدي، خو زه به دې هېڅکله پرې نږدم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_33.mp3', '', 1761754199, 1761754199),
(31342, 'Matthew 26:34', 'Matthew', 26, 34, 'عیسی ورته وویل: «په یقین سره زه تاته دا وایم چې همدا نن شپه به د چرګ د اذان نه مخکې درې ځلې ووایې چې ما نه پېژنې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_34.mp3', '', 1761754199, 1761754199),
(31343, 'Matthew 26:35', 'Matthew', 26, 35, 'پطروس ورته وویل: «که زه تا سره مړ هم شم، خو هېڅکله به ونه وایم چې تا نه پېژنم.» او نورو ټولو شاګردانو هم همداسې وویل. عیسی په جتسیماني کې دعا کوي (مرقوس ۱۴‏:‌۳۲‌‏-‌۴۲ او لوقا ۲۲‏:‌۳۹‌‏-‌۴۶)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_35.mp3', '', 1761754199, 1761754199),
(31344, 'Matthew 26:36', 'Matthew', 26, 36, 'بیا عیسی د خپلو شاګردانو سره د جتسیماني په نوم یو ځای ته ورسېده او شاګردانو ته یې وویل: «ترڅو پورې چې زه هلته ځم او دعا کوم، تاسو دلته کښېنئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_36.mp3', '', 1761754199, 1761754199),
(31345, 'Matthew 26:37', 'Matthew', 26, 37, 'هغه د پطروس او د زبدي دوه زامن د ځان سره بوتلل. هغه ډېر غمجن شو او زړه یې خفه شو', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_37.mp3', '', 1761754199, 1761754199),
(31346, 'Matthew 26:38', 'Matthew', 26, 38, 'او هغوی ته یې وویل: «زما زړه له غمه چوي او مرګ ته نژدې یم. تاسو دلته پاتې شئ او زما سره بېداره اوسئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_38.mp3', '', 1761754199, 1761754199),
(31347, 'Matthew 26:39', 'Matthew', 26, 39, 'هغه لږ لېرې لاړ، په ځمکه باندې پړمخې پرېوت او دا دعا یې وکړه: «زما پلاره، که چېرې کېدای شي، نو دا د مصیبت پیاله زما څخه لېرې کړه! خو زما رضا نه بلکې ستا رضا دې پوره شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_39.mp3', '', 1761754199, 1761754199),
(31348, 'Matthew 26:40', 'Matthew', 26, 40, 'بیا هغه بېرته شاګردانو ته راغی او ویې لیدل چې هغوی ویده دي، نو پطروس ته یې وویل: «ایا زما سره یو ساعت هم ویښ نه شوئ پاتې کېدلی؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_40.mp3', '', 1761754199, 1761754199),
(31349, 'Matthew 26:41', 'Matthew', 26, 41, 'بېداره اوسئ او دعا وکړئ چې وسوسه نه شئ. روح غواړي خو بدن کمزوری دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_41.mp3', '', 1761754199, 1761754199),
(31350, 'Matthew 26:42', 'Matthew', 26, 42, 'عیسی یوځل بیا لاړ او دعا یې وکړه: «زما پلاره، که چېرې بله لاره نه وي بې له دې چې دا پیاله وڅښم، نو ستا رضا دې پوره شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_42.mp3', '', 1761754199, 1761754199),
(31351, 'Matthew 26:43', 'Matthew', 26, 43, 'عیسی بیا راغی او ویې لیدل چې هغوی ویده وو او سترګې یې له خوبه ډکې وې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_43.mp3', '', 1761754199, 1761754199),
(31352, 'Matthew 26:44', 'Matthew', 26, 44, 'بیا عیسی هغوی پرېښودل او لاړ او د درېم ځل دپاره یې هماغه شان دعا وکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_44.mp3', '', 1761754199, 1761754199),
(31353, 'Matthew 26:45', 'Matthew', 26, 45, 'بیا هغه بېرته شاګردانو ته راغی او ورته ویې ویل: «تاسو لا ویده یئ او ارام کوئ؟ ګورئ، هغه ساعت رارسېدلی چې د انسان زوی به ګناهکارانو ته په لاس ورکول کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_45.mp3', '', 1761754199, 1761754199),
(31354, 'Matthew 26:46', 'Matthew', 26, 46, 'پاڅېږئ، راځئ چې ځو، هغه څوک چې غواړي زما سره خیانت وکړي، رارسېدلی دی.» د عیسی سره خیانت او د هغه نیول (مرقوس ۱۴‏:‌۴۳‌‏-‌۵۰ او لوقا ۲۲‏:‌۴۷‌‏-‌۵۳ او یوحنا ۱۸‏:‌۳‌‏-‌۱۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_46.mp3', '', 1761754199, 1761754199),
(31355, 'Matthew 26:47', 'Matthew', 26, 47, 'عیسی لا خبرې کولې چې یهودا چې د هغو دولسو شاګردانو څخه ؤ د ګڼ شمېر خلکو سره چې تورې او کوتکونه ورسره وو او د مشرانو کاهنانو او قومي مشرانو له خوا رالېږل شوي وو، راورسېد.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_47.mp3', '', 1761754199, 1761754199),
(31356, 'Matthew 26:48', 'Matthew', 26, 48, 'هغه خاین هغوی ته یوه نښه ورکړې وه او ورته ویلي یې وو: «څوک چې زه ښکل کړم نو دا هماغه سړی دی، هغه راونیسئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_48.mp3', '', 1761754199, 1761754199),
(31357, 'Matthew 26:49', 'Matthew', 26, 49, 'یهودا سمدلاسه عیسی ته ورغی او ورته ویې ویل: «سلام ای استاذه!» او هغه یې ښکل کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_49.mp3', '', 1761754199, 1761754199),
