(31400, 'Matthew 11:17', 'Matthew', 11, 17, '‹مونږ درته شپیلۍ ووهله، خو تاسو ګډا ونه کړه، مونږ درته د غم سندرې وویلې، خو تاسو ونه ژړل.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew11_verse_17.mp3', '', 1761754199, 1761754199),
(31401, 'Matthew 11:18', 'Matthew', 11, 18, 'ځکه کله چې یحیی راغی، نو نه یې څه خوړل او نه یې څه څښل، خو ټولو به ویل چې هغه پېریانو نیولی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew11_verse_18.mp3', '', 1761754199, 1761754199),
(31402, 'Matthew 11:19', 'Matthew', 11, 19, 'کله چې د انسان زوی راغی او هغه خوړل او څښل، خو هغوی ویل چې هغه ته ګورئ، هغه یو خېټور، شرابي او د مالیه ټولوونکو او نورو ګناهکارانو ملګری دی. خو بیاهم خلکو ته به د خدای حکمت په خپلو عملونو کې رښتینی ثابت شي.» بې‌ایمانه ښارونه (لوقا ۱۰‏:‌۱۳‌‏-‌۱۵)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew11_verse_19.mp3', '', 1761754199, 1761754199),
(31403, 'Matthew 11:20', 'Matthew', 11, 20, 'بیا عیسی د هغو ښارونو خلک ملامته کړل چې زیاتې معجزې یې په کې ښودلې وې، ځکه چې هغوی توبه ونه ویستله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew11_verse_20.mp3', '', 1761754199, 1761754199),
(31404, 'Matthew 11:21', 'Matthew', 11, 21, 'هغه وویل: «افسوس دې وي په تا ای د خورزین ښاره! او افسوس دې وي په تا باندې ای د بیت‌صیدا ښاره! ځکه که چېرې دا معجزې چې په تاسو کې وښودل شوې که هغه په صور او صیدون کې ښودل شوې وای نو هغوی به ډېر پخوا د ویر کالي اغوستي وای، په خپلو سرونو باندې به یې ایرې بادولې او توبې به یې ویستلې وای.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew11_verse_21.mp3', '', 1761754199, 1761754199),
(31405, 'Matthew 11:22', 'Matthew', 11, 22, 'خو تاسو ته وایم چې د قیامت په ورځ به د صور او صیدون سزا ستاسو د سزا څخه کمه وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew11_verse_22.mp3', '', 1761754199, 1761754199),
(31406, 'Matthew 11:23', 'Matthew', 11, 23, 'خو ای د کپرناحوم ښاره! تا غوښتل چې اسمان ته ورسېږې؟ نه، ته به دوزخ ته وغورځول شې. ځکه کومې معجزې چې په تا کې وښودل شوې، که هغه په سدوم کې ښودل شوې وای، نو هغه به تر نن ورځې پورې پاتې وای.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew11_verse_23.mp3', '', 1761754199, 1761754199),
(31407, 'Matthew 11:24', 'Matthew', 11, 24, 'خو زه تاسو ته وایم چې د قیامت په ورځ به د سدوم د خلکو سزا ستاسو د سزا څخه کمه وي.» عیسی وایي چې ماته راشئ او ارام ومومئ (لوقا ۱۰‏:‌۲۱‌‏-‌۲۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew11_verse_24.mp3', '', 1761754199, 1761754199),
(31408, 'Matthew 11:25', 'Matthew', 11, 25, 'په هغه وخت کې عیسی دا دعا وکړه: «ای پلاره، ای د ځمکې او اسمان څښتنه، ستا شکر کوم چې دا خبرې دې د پوهو او هوښیارو خلکو څخه پټې کړې دي او ناپوهو ته دې ښکاره کړي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew11_verse_25.mp3', '', 1761754199, 1761754199),
(31409, 'Matthew 11:26', 'Matthew', 11, 26, 'هو پلاره! دا ستا رضا وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew11_verse_26.mp3', '', 1761754199, 1761754199),
(31410, 'Matthew 11:27', 'Matthew', 11, 27, 'زما پلار ټول شیان ماته راسپارلي دي. هېڅوک زوی نه پېژني بې له پلاره او هېڅوک پلار نه پېژني بې له زویه او بې له هغو کسانو چې زوی یې وغواړي، پلار ورته وروښایي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew11_verse_27.mp3', '', 1761754199, 1761754199);